export const CLASS_INDEX = (() => {
  const m = {};
  for (const c of CATEGORIES)
    for (const t of c.tiers)
      for (const k of t.classes)
        m[k.id] = { ...k, category: c.name, tier: t.name, track: t.track };
  return m;
})();
